// TicksReset restores Ticks's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func TicksReset(value *Ticks) {
	value.Busy = 0
	value.Total = 0
}

func TicksMeasureBody(value *Ticks, ids *TableIds) int64 {
	bytes := int64(1)
	if value.Busy != 0 {
		bytes += tableLebBytes(ids.refAtHit(117, 0xff75d19be2aea620)) + 1 + 8
	} // busy
	if value.Total != 0 {
		bytes += tableLebBytes(ids.refAtHit(20, 0x2dcede7d543a4ffd)) + 1 + 8
	} // total
	if ids.Overflow {
		return -1
	}
	return bytes
}

func TicksMeasure(value *Ticks) int64 {
	var ids TableIds
	body := TicksMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func TicksMeasureReason(value *Ticks) (int64, error) {
	size := TicksMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
