// ReaderHoldReset restores ReaderHold's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ReaderHoldReset(value *ReaderHold) {
	value.Away = false
	value.Retired = false
	value.At = 0
	value.By = 0
	value.Held = false
	value.Reason = 0
	value.GiveBack = false
}

func ReaderHoldMeasureBody(value *ReaderHold, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ReaderHoldSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func ReaderHoldSaveBody(w *TableWriter, value *ReaderHold) bool {
	if !ReaderHoldSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
