func ReaderHoldReadStrict(wire []byte) (*ReaderHold, error) {
	var b ReaderHoldBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := ReaderHoldLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

