// SeatChangeReset restores SeatChange's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func SeatChangeReset(value *SeatChange) {
	value.Holder = 0
	value.Generation = 0
	value.From = 0
	value.At = 0
	value.By = 0
	value.Taken = false
	value.ApprovedBy = 0
	value.Reason = 0
}

