// SeatChangeReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func SeatChangeReadStrict(wire []byte) (*SeatChange, error) {
	var b SeatChangeBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := SeatChangeLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type SeatChangeBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *SeatChangeBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(SeatChange{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	SeatChangeReset((*SeatChange)(p))
	return true
}
func (b *SeatChangeBuilder) GetRoot() *SeatChange {
	if b.Arena.Locked {
		return nil
	}
	return (*SeatChange)(b.Arena.At(b.root))
}
func (b *SeatChangeBuilder) AsConst() *SeatChange {
	if len(b.region) == 0 {
		return nil
	}
	return (*SeatChange)(unsafe.Pointer(&b.region[0]))
}
